import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment, balanceDue } from '../src/payments.js';

test('exportCsv returns empty CSV with only header for empty invoices', () => {
  const result = exportCsv([]);
  assert.equal(result.ok, true);
  assert.equal(result.value, 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n');
});

test('exportCsv includes header line', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);

  const result = exportCsv([issuedResult.value]);
  assert.equal(result.ok, true);
  const lines = result.value.split('\n');
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
});

test('exportCsv includes invoice number', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const result = exportCsv([invoice]);
  assert.equal(result.ok, true);
  const lines = result.value.split('\n');
  assert(lines[1].startsWith(invoice.number + ','));
});

test('exportCsv includes customer name', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);

  const result = exportCsv([issuedResult.value]);
  assert.equal(result.ok, true);
  const lines = result.value.split('\n');
  assert(lines[1].includes('Alice'));
});

test('exportCsv includes issue date', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);

  const result = exportCsv([issuedResult.value]);
  assert.equal(result.ok, true);
  const lines = result.value.split('\n');
  assert(lines[1].includes('2025-10-01'));
});

test('exportCsv includes due date', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const result = exportCsv([invoice]);
  assert.equal(result.ok, true);
  const lines = result.value.split('\n');
  assert(lines[1].includes(invoice.dueDate));
});

test('exportCsv includes status', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const result = exportCsv([invoice]);
  assert.equal(result.ok, true);
  const lines = result.value.split('\n');
  assert(lines[1].includes('issued'));
});

test('exportCsv formats amounts with 2 decimals', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);

  const result = exportCsv([issuedResult.value]);
  assert.equal(result.ok, true);
  const lines = result.value.split('\n');
  const fields = lines[1].split(',');
  const subtotal = fields[5];
  assert(subtotal.includes('.'));
  const [euros, cents] = subtotal.split('.');
  assert.equal(cents.length, 2);
});

test('exportCsv uses dot as decimal separator', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);

  const result = exportCsv([issuedResult.value]);
  assert.equal(result.ok, true);
  const csv = result.value;
  assert(!csv.includes(',00€'));
  assert(csv.includes('.'));
});

test('exportCsv has no currency sign', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);

  const result = exportCsv([issuedResult.value]);
  assert.equal(result.ok, true);
  const csv = result.value;
  assert(!csv.includes('€'));
});

test('exportCsv has no thousands separator', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);

  const result = exportCsv([issuedResult.value]);
  assert.equal(result.ok, true);
  const csv = result.value;
  assert(!csv.includes(',0'));
});

test('exportCsv escapes fields with commas', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);

  const result = exportCsv([issuedResult.value]);
  assert.equal(result.ok, true);
  const lines = result.value.split('\n');
  const fields = lines[1].split(',');
  const customerField = lines[1].includes('"');
  assert(customerField);
});

test('exportCsv escapes fields with double quotes', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const result = exportCsv([invoice]);
  assert.equal(result.ok, true);
  const csv = result.value;
  const lines = csv.split('\n');
  assert(lines[1]);
});

test('exportCsv lines end with newline', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);

  const result = exportCsv([issuedResult.value]);
  assert.equal(result.ok, true);
  assert(result.value.endsWith('\n'));
});

test('exportCsv includes multiple invoices', () => {
  const invoice1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const invoice2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issued1 = issueInvoice(invoice1Result.value, []);
  const issued2 = issueInvoice(invoice2Result.value, ['INV-2025-0001']);

  const result = exportCsv([issued1.value, issued2.value]);
  assert.equal(result.ok, true);
  const lines = result.value.split('\n');
  assert.equal(lines.length, 4);
});

test('exportCsv includes draft invoices with DRAFT number', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result = exportCsv([invoiceResult.value]);
  assert.equal(result.ok, true);
  const lines = result.value.split('\n');
  assert(lines[1].startsWith('DRAFT,'));
});

test('exportCsv includes invoice totals correctly', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const totals = invoiceTotals(invoice);

  const result = exportCsv([invoice]);
  assert.equal(result.ok, true);
  const lines = result.value.split('\n');
  const expected = `${invoice.number},Alice,2025-10-01,${invoice.dueDate},issued,${(totals.subtotal / 100).toFixed(2)},${(totals.discount / 100).toFixed(2)},${(totals.vat / 100).toFixed(2)},${(totals.total / 100).toFixed(2)}`;
  assert(lines[1].startsWith(expected));
});

test('exportCsv includes due amount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const due = balanceDue(invoice);

  const result = exportCsv([invoice]);
  assert.equal(result.ok, true);
  const lines = result.value.split('\n');
  assert(lines[1].includes((due / 100).toFixed(2)));
});

test('exportCsv reflects partial payments in due amount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const paymentResult = recordPayment(invoice, { amount: 10000, date: '2025-10-02' });
  const due = balanceDue(paymentResult.value);

  const result = exportCsv([paymentResult.value]);
  assert.equal(result.ok, true);
  const lines = result.value.split('\n');
  assert(lines[1].endsWith((due / 100).toFixed(2)));
});

test('exportCsv includes different statuses', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const totals = invoiceTotals(invoice);
  const paymentResult = recordPayment(invoice, { amount: totals.total, date: '2025-10-02' });

  const result = exportCsv([paymentResult.value]);
  assert.equal(result.ok, true);
  const lines = result.value.split('\n');
  assert(lines[1].includes('paid'));
});

test('exportCsv maintains invoice order', () => {
  const invoice1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const invoice2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-02',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issued1 = issueInvoice(invoice1Result.value, []);
  const issued2 = issueInvoice(invoice2Result.value, ['INV-2025-0001']);

  const result = exportCsv([issued1.value, issued2.value]);
  assert.equal(result.ok, true);
  const lines = result.value.split('\n');
  assert(lines[1].includes(issued1.value.number));
  assert(lines[2].includes(issued2.value.number));
});

